import os, glob

def read_fasta(filepath):
    sequences = []
    current_header = None
    current_seq = []
    with open(filepath, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('>'):
                if current_header is not None:
                    sequences.append((current_header, ''.join(current_seq)))
                current_header = line[1:]
                current_seq = []
            else:
                current_seq.append(line)
        if current_header is not None:
            sequences.append((current_header, ''.join(current_seq)))
    return sequences

# Check .mafft files: are they all aligned with 4 sequences?
maffts = sorted(glob.glob('/workspace/work/scogs_fungi/*.faa.mafft'))
issues = []
nseq_counts = {}
for f in maffts:
    seqs = read_fasta(f)
    lengths = [len(s[1]) for s in seqs]
    n = len(seqs)
    nseq_counts[n] = nseq_counts.get(n, 0) + 1
    if len(set(lengths)) > 1:
        issues.append((os.path.basename(f), lengths))

print(f'Sequence count distribution: {nseq_counts}')
print(f'Files with unequal lengths: {len(issues)}')
if issues:
    for name, lengths in issues[:5]:
        print(f'  {name}: {lengths}')
" 2>&1

